DELETED = []
root = Path(__file__).resolve().parent
for name, digest in EXPECTED.items():
    p = root / name
    if p.is_symlink() or not p.is_file() or hashlib.sha256(p.read_bytes()).hexdigest() != digest:
        raise SystemExit('Source byte mismatch: ' + name)
for name in DELETED:
    if (root / name).exists() or (root / name).is_symlink():
        raise SystemExit('Deleted file remains: ' + name)
print(f'Verified {len(EXPECTED)} snapshot files and {len(DELETED)} deletions')
